export function ensureDiversifiedEmpire(s){s.diversifiedAssets??=[];s.rivals??=[{id:1,name:"Northstar Global",value:8200000,strength:72},{id:2,name:"Vertex Industries",value:5600000,strength:61},{id:3,name:"Meridian Capital",value:3900000,strength:54}];s.empireEvents??=[];s.executives??=[];s.ipos??=[];s.loans??=[];s.contractOffers??=[];s.activeContracts??=[];s.empireProjects??=[];}
export function buyDiversifiedAsset(s,id){ensureDiversifiedEmpire(s);const a=DIVERSIFIED_ASSETS.find(x=>x.id===id);if(!a)throw Error("Nie znaleziono inwestycji.");if(s.diversifiedAssets.some(x=>x.id===id))throw Error("To aktywo jest już w portfolio.");if(s.cash<a.cost)throw Error("Za mało gotówki na tę inwestycję.");s.cash-=a.cost;s.diversifiedAssets.push({...a,boughtDay:s.day});return a;}
export function processDiversifiedEmpireDay(s){ensureDiversifiedEmpire(s);if(!s.contractOffers.length&&s.activeContracts.length<3){const offers=[["Dostawa dla administracji",45000,5,12000],["Kontrakt infrastrukturalny",72000,7,19000],["Usługi dla korporacji",56000,6,15000],["Projekt badawczy",88000,8,24000],["Obsługa sieci handlowej",39000,4,9000]];const q=offers[Math.floor(Math.random()*offers.length)];s.contractOffers.push({id:(s.nextContractId=(s.nextContractId||0)+1),name:q[0],reward:q[1],duration:q[2],cost:q[3],daysLeft:q[2]});}let contractNet=0;s.activeContracts=s.activeContracts.filter(c=>{c.daysLeft--;contractNet-=c.cost;if(c.daysLeft<=0){s.cash+=c.reward;contractNet+=c.reward;return false;}return true;});s.loans=s.loans.filter(l=>{const pay=Math.min(l.installment,l.balance);s.cash-=pay;l.balance-=pay;l.daysLeft--;if(l.balance<=0||l.daysLeft<=0){if(l.balance>0)s.cash-=l.balance;return false;}return true;});s.empireProjects=s.empireProjects.filter(p=>{p.daysLeft--;if(p.daysLeft<=0){p.active=false;s.projectIncome=(s.projectIncome||0)+p.bonus;s.completedEmpireProjects??=[];s.completedEmpireProjects.push(p.id);return false;}return true;});const multiplier=s.empireEventMultiplier||1,income=Math.round(s.diversifiedAssets.reduce((n,x)=>n+x.revenue,0)*multiplier),assetCost=s.diversifiedAssets.reduce((n,x)=>n+x.upkeep,0),payroll=(s.executives||[]).reduce((n,x)=>n+(Number(x.salary)||0),0),projectIncome=Number(s.projectIncome)||0,cost=assetCost+payroll;s.cash+=income-cost+projectIncome+contractNet;s.diversifiedRevenue=income;s.diversifiedCosts=cost;s.rivals.forEach(r=>{r.value=Math.max(500000,Math.round(r.value*(1+(Math.random()-.46)*.025)));r.strength=Math.max(20,Math.min(100,r.strength+Math.round((Math.random()-.5)*2)));});if(Math.random()<.075){const events=[["Boom inwestycyjny","Wzrost popytu na aktywa.",1.08],["Kryzys surowcowy","Koszty rosną w całej gospodarce.",.94],["Nowe regulacje","Branże dostosowują działalność.",.97],["Przełom rynkowy","Wyceny innowacyjnych biznesów rosną.",1.06],["Spowolnienie gospodarcze","Przychody aktywów chwilowo spadają.",.92]],e=events[Math.floor(Math.random()*events.length)];s.empireEvents.unshift({title:e[0],detail:e[1],day:s.day});s.empireEvents=s.empireEvents.slice(0,8);s.empireEventMultiplier=e[2];}else s.empireEventMultiplier=1;return {income,cost,net:income-cost+projectIncome+contractNet,contractNet,projectIncome};}
export function listCompanyOnExchange(s,id,exchangeId){const c=s.companies.find(x=>x.id===id);if(!c)throw Error("Nie znaleziono spółki.");if(Number(c.share??100)<50)throw Error("Do IPO potrzebujesz minimum 50% udziałów.");if(s.market.some(x=>x.name===c.name))throw Error("Ta spółka jest już notowana.");const value=Math.max(100000,Number(c.value)||100000),share=Math.max(10,Number(c.share)||100),listed={id:Math.max(0,...s.market.map(x=>Number(x.id)||0))+1,name:c.name,industry:c.industry||"Biznes",value,share,dividend:.0015,freeFloat:100-share,shares:Math.round(value/10),eps:2,pe:15,boardSeats:5,history:[value],shareholders:[],controlled:true,sourceCompanyId:c.id,exchange:EXCHANGES.some(x=>x.id===exchangeId)?exchangeId:undefined};s.market.push(listed);c.listed=true;s.ipos.push({name:c.name,day:s.day,value});return listed;}
export function acquireRival(s,id){ensureDiversifiedEmpire(s);const r=s.rivals.find(x=>x.id===id);if(!r)throw Error("Nie znaleziono konkurenta.");const price=Math.round(r.value*(1.15+r.strength/500));if(s.cash<price)throw Error("Za mało gotówki na przejęcie. Cena: "+price.toLocaleString("pl-PL")+" zł.");s.cash-=price;s.acquiredRivals??=[];s.acquiredRivals.push({...r,acquiredDay:s.day,price});s.rivals=s.rivals.filter(x=>x.id!==id);return {rival:r,price};}
export function hireExecutive(s,role,name){if(s.cash<45000)throw Error("Rekrutacja dyrektora wymaga 45 000 zł.");s.cash-=45000;s.executives??=[];s.executives.push({id:(s.executives.length+1),role,name:name||"Nowy dyrektor",salary:900});return s.executives.at(-1);}

