export function takeEmpireLoan(s,amount){ensureDiversifiedEmpire(s);amount=Math.floor(Number(amount));if(![100000,250000,500000,1000000].includes(amount))throw Error("Wybierz jeden z dostępnych pakietów kredytowych.");s.loans??=[];if(s.loans.length>=3)throw Error("Możesz mieć maksymalnie trzy aktywne kredyty.");const rate=.0065,days=30,installment=Math.ceil(amount*(1+rate*days)/days);s.cash+=amount;s.loans.push({id:(s.nextLoanId=(s.nextLoanId||0)+1),principal:amount,balance:Math.ceil(amount*(1+rate*days)),installment,daysLeft:days,rate});return s.loans.at(-1);}
export function repayEmpireLoan(s,id){const loan=s.loans?.find(x=>x.id===Number(id));if(!loan)throw Error("Nie znaleziono kredytu.");const amount=loan.balance;if(s.cash<amount)throw Error("Do spłaty potrzeba "+amount.toLocaleString("pl-PL")+" zł.");s.cash-=amount;s.loans=s.loans.filter(x=>x.id!==loan.id);return amount;}
export function acceptEmpireContract(s,id){ensureDiversifiedEmpire(s);s.contractOffers??=[];s.activeContracts??=[];const c=s.contractOffers.find(x=>x.id===Number(id));if(!c)throw Error("Ta oferta wygasła.");if(s.activeContracts.length>=3)throw Error("Możesz realizować maksymalnie trzy kontrakty naraz.");s.contractOffers=s.contractOffers.filter(x=>x.id!==c.id);s.activeContracts.push({...c,daysLeft:c.duration});return c;}
export function startEmpireProject(s,id){ensureDiversifiedEmpire(s);s.empireProjects??=[];const p=EMPIRE_PROJECTS.find(x=>x.id===id);if(!p)throw Error("Nie znaleziono projektu.");if(s.empireProjects.some(x=>x.id===id))throw Error("Ten projekt został już uruchomiony.");if(s.cash<p.cost)throw Error("Za mało gotówki na projekt.");s.cash-=p.cost;s.empireProjects.push({...p,daysLeft:p.days,active:true});return p;}

